@pytest.mark.parametrize("configured", [False, True]) def test_studio_native_server_uploads_use_private_startup_storage( tmp_path: Path, configured: bool, ) -> None: # Execute the actual startup/handler in a child; no worker, model or legacy submission. with socket.socket() as reservation: reservation.bind(("127.0.0.1", 0)) port = reservation.getsockname()[1] env = dict(os.environ, PYTHONUNBUFFERED="1", LOCALAPPDATA=str(tmp_path), HOME=str(tmp_path)) env.pop("HAWEDIT_STUDIO_STORAGE_ROOT", None) env.pop("HAWEDIT_UPLOAD_MAX_BYTES", None) root = tmp_path / ("HawEditStudio" if os.name == "nt" else ".hawedit-studio") if configured: root = tmp_path / "configured-private-studio" env["HAWEDIT_STUDIO_STORAGE_ROOT"] = str(root) program = ( "import sys; from pathlib import Path; import hawedit.web as w; " "assert w.UPLOAD_STORE is None; " "w.JOB_MANAGER = w.JobManager(Path(sys.argv[2])); " "w.run_web_server(int(sys.argv[1]))" ) process = subprocess.Popen( [sys.executable, "-c", program, str(port), str(tmp_path / "test-only-history")], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, ) base = f"http://127.0.0.1:{port}" try: deadline = time.monotonic() + 20 while True: assert process.poll() is None, "Native studio startup failed" try: with urlopen(base + "/", timeout=1) as response: assert response.status == 200 and b"HawEdit" in response.read() break except URLError: assert time.monotonic() < deadline, "Native studio startup timed out" time.sleep(0.05) data = MEDIA.read_bytes() payload = json.dumps({"filename": "real-selected-video.mp4", "size": len(data)}).encode() with urlopen( Request( base + "/api/uploads", data=payload, headers={"Content-Type": "application/json"} ), timeout=10, ) as response: assert response.status == 201 upload_id = json.load(response)["upload_id"] with urlopen( Request(base + f"/api/uploads/{upload_id}", data=data, method="PUT"), timeout=30 ) as response: assert response.status == 201 source = json.load(response) with urlopen(base + f"/api/uploads/{upload_id}", timeout=10) as response: > assert json.load(response)["source_id"] == source["source_id"] == upload_id ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E KeyError: 'source_id'
